<script setup lang="ts">
import ConsoleDialog from '@/components/ConsoleDialog.vue'
import {ref,onMounted} from 'vue'
import api from '@/api/client'
import {list} from '@/utils/display'
interface Rule {id:number;did_id?:number;name:string;priority:number;enabled:boolean;condition_type:string;condition_data?:{pattern?:string;start_hour?:number;end_hour?:number;days?:number[]};action_type:string;action_data?:{devices?:number[];number?:string;timeout?:number}}
interface DID {id:number;phone_number:string;friendly_name?:string}
interface Account {id:number;name:string;username:string;enabled:boolean;state:string}
const routes=ref<Rule[]>([]),dids=ref<DID[]>([]),accounts=ref<Account[]>([]),error=ref(''),busy=ref(false),show=ref(false),editing=ref<Rule|null>(null)
const fresh=()=>({name:'',did_id:0,priority:0,enabled:true,condition_type:'default',pattern:'',start_hour:9,end_hour:17,days:[] as number[],action_type:'ring',devices:[] as number[],number:'',timeout:30})
const form=ref(fresh())
const excluded=ref<string[]>([])
const locked=(id?:number)=>id?excluded.value.includes(number(id)):excluded.value.length>0
const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat']
function errorText(e:unknown){return (e as {response?:{data?:{error?:{message?:string}}}}).response?.data?.error?.message||'Could not complete the routing request'}
async function load(){error.value='';try{const [r,d,a,p]=await Promise.all([api.get('/routes'),api.get('/dids'),api.get('/business/accounts'),api.get('/business/excluded-numbers')]);excluded.value=p.data.data.map((entry:{number:string})=>entry.number);routes.value=list(r.data.data);dids.value=list(d.data.data);accounts.value=list(a.data.data)}catch(e){error.value=errorText(e)}}
function open(rule:Rule|null=null){editing.value=rule;form.value=rule?{...fresh(),name:rule.name,did_id:rule.did_id||0,priority:rule.priority,enabled:rule.enabled,condition_type:rule.condition_type,pattern:rule.condition_data?.pattern||'',start_hour:rule.condition_data?.start_hour??9,end_hour:rule.condition_data?.end_hour??17,days:[...(rule.condition_data?.days||[])],action_type:rule.action_type,devices:[...(rule.action_data?.devices||[])],number:rule.action_data?.number||'',timeout:rule.action_data?.timeout||30}:fresh();show.value=true;error.value=''}
async function save(){busy.value=true;error.value='';try{const f=form.value;const payload={name:f.name,did_id:f.did_id,priority:f.priority,enabled:f.enabled,condition_type:f.condition_type,condition_data:f.condition_type==='callerid'?{pattern:f.pattern}:f.condition_type==='time'?{start_hour:f.start_hour,end_hour:f.end_hour,days:f.days}:{},action_type:f.action_type,action_data:f.action_type==='ring'?{devices:f.devices,timeout:f.timeout,fallback:'voicemail'}:f.action_type==='forward'?{number:f.number}:{}};if(editing.value)await api.put(`/routes/${editing.value.id}`,payload);else await api.post('/routes',payload);show.value=false;await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function toggle(rule:Rule){busy.value=true;try{await api.put(`/routes/${rule.id}`,{...rule,enabled:!rule.enabled});await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function number(id?:number){return dids.value.find(d=>d.id===id)?.phone_number||'All local numbers'}
function action(rule:Rule){if(rule.action_type==='ring')return 'Ring '+(rule.action_data?.devices||[]).map(id=>accounts.value.find(a=>a.id===id)?.username||`User ${id}`).join(', ');if(rule.action_type==='forward')return 'Forward to '+(rule.action_data?.number||'—');return rule.action_type}
onMounted(load)
</script>
<template><div class="space-y-6"><div class="flex flex-wrap justify-between gap-4"><div><h1 class="text-3xl">Call routing</h1><p class="text-sm text-gray-500 mt-2">Local incoming rules. Smaller priorities run first. These controls do not change Twilio number connections.</p></div><div class="flex gap-2"><button class="border rounded px-4 py-2" @click="load" :disabled="busy">Refresh</button><button class="bg-primary text-white rounded px-4 py-2" @click="open()">Add route</button></div></div>
<p v-if="error" role="alert" class="text-red-600">{{error}}</p>
<div class="glass rounded-lg overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th class="p-4">Rule / number</th><th class="p-4">Priority / condition</th><th class="p-4">Action</th><th class="p-4">Controls</th></tr></thead><tbody><tr v-for="r in routes" :key="r.id" class="border-t"><td class="p-4">{{r.name}}<p class="text-gray-500">{{number(r.did_id)}}</p><p v-if="locked(r.did_id)" class="text-amber-700">Excluded from configuration</p></td><td class="p-4">{{r.priority}} · {{r.condition_type}}<p v-if="r.condition_type==='time'" class="text-gray-500">{{r.condition_data?.start_hour}}:00–{{r.condition_data?.end_hour}}:00 server time</p><p v-if="r.condition_type==='callerid'">Contains {{r.condition_data?.pattern}}</p></td><td class="p-4">{{action(r)}}</td><td class="p-4"><div class="flex gap-4"><button @click="open(r)" :disabled="busy||locked(r.did_id)" class="text-primary">Edit</button><button @click="toggle(r)" :disabled="busy||locked(r.did_id)" class="border px-3 py-1 rounded">{{r.enabled?'Enabled':'Disabled'}}</button></div></td></tr><tr v-if="!routes.length"><td class="p-8 text-gray-500" colspan="4">No local rules. Unmatched incoming calls use voicemail.</td></tr></tbody></table></div>
<ConsoleDialog v-if="show" :label="editing ? 'Edit route' : 'Add route'" @close="!busy && (show=false)"><form @submit.prevent="save" class="space-y-4"><h2 class="text-xl">{{editing?'Edit route':'Add route'}}</h2><label class="block">Name<input v-model="form.name" required maxlength="128" class="block w-full border rounded p-2 mt-1" /></label><label class="block">Business number<select v-model.number="form.did_id" required class="block w-full border rounded p-2 mt-1"><option :value="0" disabled>Select a local number</option><option v-for="d in dids.filter(d=>!excluded.includes(d.phone_number))" :key="d.id" :value="d.id">{{d.phone_number}}</option></select></label><label class="block">Priority<input v-model.number="form.priority" type="number" min="0" max="10000" required class="block w-full border rounded p-2 mt-1" /></label><label class="block">Condition<select v-model="form.condition_type" class="block w-full border rounded p-2 mt-1"><option value="default">Always / default</option><option value="callerid">Caller number contains</option><option value="time">Time window</option></select></label><input v-if="form.condition_type==='callerid'" v-model="form.pattern" aria-label="Caller number contains" required placeholder="+44" class="w-full border rounded p-2" /><div v-if="form.condition_type==='time'" class="space-y-3"><p class="text-sm text-gray-500">Hours use the server timezone. Same-day windows only. No weekdays selected means every day.</p><div class="flex gap-3"><label>Start hour<input v-model.number="form.start_hour" type="number" min="0" max="23" required class="w-full border rounded p-2" /></label><label>End hour<input v-model.number="form.end_hour" type="number" :min="form.start_hour+1" max="24" required class="w-full border rounded p-2" /></label></div><div class="flex flex-wrap gap-3"><label v-for="(day,index) in days" :key="day" class="flex gap-1"><input v-model="form.days" type="checkbox" :value="index" />{{day}}</label></div></div><label class="block">Action<select v-model="form.action_type" class="block w-full border rounded p-2 mt-1"><option value="ring">Ring SIP users</option><option value="forward">Forward to telephone number</option><option value="voicemail">Voicemail</option><option value="reject">Reject</option></select></label><div v-if="form.action_type==='ring'" class="space-y-3"><label v-for="a in accounts.filter(a=>a.enabled&&a.state==='ready')" :key="a.id" class="flex gap-2"><input v-model="form.devices" type="checkbox" :value="a.id" />{{a.name}} · {{a.username}}</label><label class="block">Ring seconds<input v-model.number="form.timeout" type="number" min="5" max="120" required class="w-full border rounded p-2 mt-1" /></label></div><label v-if="form.action_type==='forward'" class="block">Forward number<input v-model="form.number" required pattern="\+[1-9][0-9]{7,14}" placeholder="+country-code-number" class="block w-full border rounded p-2 mt-1" /><span class="text-sm text-gray-500">Forwarded calls incur Twilio charges and must follow your outgoing country policy.</span></label><label class="flex gap-2"><input v-model="form.enabled" type="checkbox" />Enabled</label><p v-if="error" class="text-red-600">{{error}}</p><p class="text-sm text-gray-500">Saving affects future incoming calls on this number. Existing calls and Twilio webhooks remain unchanged.</p><div class="dialog-actions"><button type="button" @click="show=false" :disabled="busy" class="border rounded px-4 py-2">Cancel</button><button :disabled="busy||!form.did_id||(form.action_type==='ring'&&!form.devices.length)" class="bg-primary text-white rounded px-4 py-2">Save route</button></div></form></ConsoleDialog></div></template>
